    @discardableResult
    func store(chunks: [Data], for key: ReadAloudAudioCacheKey) -> Bool {
        let bytes = chunks.reduce(into: 0) { $0 += $1.count }
        guard !chunks.isEmpty, bytes > 0, bytes <= maximumBytes else {
